import { useEffect, useState } from 'react';
import { AnimatePresence } from 'motion/react';
import { introPending } from '../../lib/signature.js';
import { PaperGrain } from '../../components/shader/PaperBackdrop.jsx';
import { Gate } from './gate/Gate.jsx';
import { Nav } from './sections/Nav.jsx';
import { Hero } from './sections/Hero.jsx';
import { Ticker } from './sections/Ticker.jsx';
import { Problem } from './scenes/Problem.jsx';
import { Journey } from './scenes/Journey.jsx';
import { AgentGraph } from './scenes/AgentGraph.jsx';
import { Crash } from './scenes/Crash.jsx';
import { Detections } from './sections/Detections.jsx';
import { EvidenceMock } from './scenes/EvidenceMock.jsx';
import { LedgerTrack } from './scenes/LedgerTrack.jsx';
import { Altimeter } from './scenes/Altimeter.jsx';
import { Facts } from './sections/Facts.jsx';
import { Faq } from './sections/Faq.jsx';
import { Closing } from './sections/Closing.jsx';
import { Footer } from './sections/Footer.jsx';
import { useSmoothScroll } from './useSmoothScroll.js';
import './landing.css';
import './scenes/scenes.css';

/** Marketing site, told as one refund's story. Static sections live in
 *  ./sections, scroll-driven pinned scenes in ./scenes, the intro in ./gate. */
export function LandingPage() {
  const [intro, setIntro] = useState(introPending);
  useSmoothScroll();

  // A reload starts at the top with the intro, not mid-story under it.
  useEffect(() => {
    if ('scrollRestoration' in window.history) window.history.scrollRestoration = 'manual';
    if (introPending()) window.scrollTo(0, 0);
  }, []);
  // Freeze smooth scrolling while the intro is up.
  useEffect(() => {
    if (intro) window.__lenis?.stop();
    else window.__lenis?.start();
  }, [intro]);

  return (
    <div className="lp">
      <AnimatePresence>{intro && <Gate onDone={() => setIntro(false)} />}</AnimatePresence>
      <PaperGrain opacity={0.35} />
      <Nav />
      <Altimeter />
      <main>
        <Hero />
        <Ticker />
        <Problem />
        <Journey />
        <AgentGraph />
        <Crash />
        <Detections />
        <EvidenceMock />
        <LedgerTrack />
        <Facts />
        <Faq />
        <Closing />
      </main>
      <Footer onReplayIntro={() => { window.scrollTo(0, 0); setIntro(true); }} />
    </div>
  );
}
import { Link } from 'react-router-dom';
import { motion } from 'motion/react';
import { HandIcon } from '../../../components/icons/HandIcon.jsx';
import { SketchArrow, SketchCircle } from '../../../components/sketch/Sketch.jsx';
import { DitherField } from '../../../components/shader/PaperBackdrop.jsx';
import { MaskWords } from '../Reveal.jsx';
import { HeroSpecimen } from './HeroSpecimen.jsx';
import { AskBar } from './AskBar.jsx';
import { Magnetic } from '../../../components/fx/Magnetic.jsx';

const META = [
  ['For', 'Support teams refunding on Stripe or Shopify'],
  ['Proves', 'Every refund, read back from Stripe before it counts'],
  ['Earns', 'More freedom only when the evidence beats your break-even'],
];

export function Hero() {
  return (
    <section className="lp-hero" id="top">
      <div className="lp-hero-grid">
        <div className="lp-hero-copy">
          <motion.p className="mono lp-kicker" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.1 }}>
            (001) - Earned-autonomy agents
          </motion.p>
          <h1 className="lp-h1 serif">
            <MaskWords text="Autonomy" animateOnMount />
            <br />
            <MaskWords text="is" animateOnMount delay={0.12} />{' '}
            <SketchCircle delay={1.1}><em className="italic"><MaskWords text="earned," animateOnMount delay={0.18} /></em></SketchCircle>
            <br />
            <MaskWords text="not assumed." animateOnMount delay={0.26} />
          </h1>
          <motion.p
            className="lp-lede"
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.6, duration: 0.8 }}
          >
            An AI agent that answers refund emails end to end - and has to <b>earn</b> the right to
            pay out alone. Every refund is checked in Stripe; one bad result drops it to zero.
          </motion.p>
          <motion.div className="lp-hero-cta" initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.75, duration: 0.8 }}>
            <AskBar />
            <Magnetic><Link to="/onboarding" className="btn btn-ink">Set up your agent <HandIcon name="arrow-right" size={16} /></Link></Magnetic>
            <Magnetic><a href="#journey" className="btn btn-line">See how it earns</a></Magnetic>
          </motion.div>
        </div>

        <motion.div
          className="lp-hero-visual"
          initial={{ opacity: 0, clipPath: 'inset(0 0 100% 0)' }}
          animate={{ opacity: 1, clipPath: 'inset(0 0 0% 0)' }}
          transition={{ duration: 1.3, delay: 0.2, ease: [0.22, 1, 0.36, 1] }}
        >
          <DitherField className="lp-hero-shader" shape="warp" speed={0.25} size={2.4} />
          <HeroSpecimen />
          <div className="lp-note lp-note-b hand">
            <SketchArrow width={70} height={46} d="M64 42 C 44 40, 20 30, 8 6" end={[8, 6, -2.1]} delay={2} />
            one bad write → L0
          </div>
        </motion.div>
      </div>

      <div className="lp-hero-meta">
        {META.map(([k, v], i) => (
          <motion.div key={k} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.9 + i * 0.1 }}>
            <span className="mono muted">{k}</span>
            <p>{v}</p>
          </motion.div>
        ))}
      </div>
    </section>
  );
}
import { useEffect, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { SketchBox } from '../../../components/sketch/Sketch.jsx';
import { HandIcon } from '../../../components/icons/HandIcon.jsx';

/* A looping specimen of one task class's life: three clean runs promote it,
   then a quiet failure is caught and the dial crashes. Illustrative only -
   the real thing runs in the app against the API. */
const FRAMES = [
  { level: 1, runs: 0, line: 'ORD-1001 · $25.00 · drafted for approval', icon: 'message' },
  { level: 1, runs: 1, line: 'ORD-1003 · $15.00 · executed · read-back matched', icon: 'check' },
  { level: 1, runs: 2, line: 'ORD-1002 · $40.00 · executed · read-back matched', icon: 'check' },
  { level: 2, runs: 0, line: '3 clean runs → promoted to L2 · commit 4f1a2c', icon: 'commit' },
  { level: 2, runs: 1, line: 'ORD-1005 · $45.00 · executed · read-back matched', icon: 'check' },
  { level: 0, runs: 0, line: 'state_mismatch - tool said done, DB moved $0.00', icon: 'warn', alert: true },
];

export function HeroSpecimen() {
  const [i, setI] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setI((n) => (n + 1) % FRAMES.length), 2200);
    return () => clearInterval(t);
  }, []);
  const f = FRAMES[i];

  return (
    <SketchBox className="lp-specimen" seed={77}>
      <div className="lp-specimen-top">
        <span className="mono">task class / refund</span>
        <span className={`mono ${f.alert ? 'lp-alert' : ''}`}>{f.alert ? '● quarantined' : '● live'}</span>
      </div>
      <div className="lp-specimen-level">
        <AnimatePresence mode="wait" initial={false}>
          <motion.span
            key={f.level}
            className="serif"
            initial={{ y: 40, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: -40, opacity: 0 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
          >
            L{f.level}
          </motion.span>
        </AnimatePresence>
        <div className="lp-specimen-rungs">
          {[0, 1, 2, 3].map((r) => (
            <motion.i key={r} animate={{ backgroundColor: r <= f.level && !f.alert ? '#0e0e0d' : 'rgba(0,0,0,0)' }} />
          ))}
        </div>
      </div>
      <div className="lp-specimen-runs">
        <span className="mono muted">clean runs</span>
        <span className="lp-ticks">
          {[0, 1, 2].map((r) => <i key={r} className={r < f.runs ? 'on' : ''} />)}
        </span>
      </div>
      <AnimatePresence mode="wait">
        <motion.p
          key={i}
          className={`lp-specimen-line ${f.alert ? 'lp-alert' : ''}`}
          initial={{ opacity: 0, x: 10 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -10 }}
          transition={{ duration: 0.3 }}
        >
          <HandIcon name={f.icon} size={16} /> {f.line}
        </motion.p>
      </AnimatePresence>
    </SketchBox>
  );
}

