        <AgentGraph />
        <Crash />
        <Detections />
        <EvidenceMock />
        <LedgerTrack />
        <Facts />
        <Faq />
        <Closing />
      </main>
      <Footer onReplayIntro={() => { window.scrollTo(0, 0); setIntro(true); }} />
    </div>
  );
}
