function Scene({ p }) {
  const [stage, setStage] = useState(0);
  useMotionValueEvent(p, 'change', (v) => setStage(v < 0.12 ? 0 : v < 0.42 ? 1 : v < 0.72 ? 2 : 3));
  const dark = stage >= 1 && stage < 3 ? true : stage === 3;
  const lines = stage === 0 ? 1 : stage === 1 ? 4 : 5;

  useEffect(() => {
