    ("import { Faq } from './sections/Faq.jsx';\n", "import { Faq } from './sections/Faq.jsx';\nimport { Install } from './sections/Install.jsx';\n"),
    ("        <Facts />\n        <Faq />\n", "        <Install />\n        <Facts />\n        <Faq />\n"),
])
